"use client";

import { type Metadata } from "next";
import { ClerkProvider } from "@clerk/nextjs";
import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";
import ScrollLock from "./scroll-lock"; // 👈 nhớ import scroll-lock
import { usePathname } from "next/navigation";

const geistSans = Geist({ variable: "--font-geist-sans", subsets: ["latin"] });
const geistMono = Geist_Mono({ variable: "--font-geist-mono", subsets: ["latin"] });

export const metadata: Metadata = {
  title: "AskThemAll AI",
  description: "Generated by create next app",
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  const pathname = usePathname();

  return (
    <ClerkProvider>
      <html lang="vi" className="min-h-dvh overflow-x-hidden">
        <body
          className={`${geistSans.variable} ${geistMono.variable} antialiased min-h-dvh bg-[#F6FBF1]`}
        >
          {pathname === "/" && <ScrollLock />} {/* ✅ Chỉ khóa cuộn trang chủ */}
          {children}
        </body>
      </html>
    </ClerkProvider>
  );
}
